import React, { useState, useEffect, useCallback } from 'react';
import { MatrixInput } from './MatrixInput';
import { MatrixTextInput } from './MatrixTextInput';
import { FileUpload } from './FileUpload';
import { ResultsDisplay } from './ResultsDisplay';
import { IterationTable } from './IterationTable';
import { Alert } from '../common/Alert';
import { Loader } from '../common/Loader';
import { lab1Api } from '../../services/api';
import { SolutionResponse, FileData } from '../../types';
import { Play, FileText, Keyboard, Grid3x3, RefreshCw } from 'lucide-react';
import toast from 'react-hot-toast';
import {formatMatrixToString, parseMatrixText} from '../../utils/matrixParser';

type InputMode = 'manual' | 'text' | 'file';

export const SLAUPage: React.FC = () => {
    const [n, setN] = useState<number>(3);
    const [inputMode, setInputMode] = useState<InputMode>('manual');
    const [matrix, setMatrix] = useState<number[][]>(
        Array(3).fill(0).map(() => Array(3).fill(0))
    );
    const [vector, setVector] = useState<number[]>(Array(3).fill(0));
    const [textValue, setTextValue] = useState<string>('');
    const [epsilon, setEpsilon] = useState<number>(0.0001);
    const [maxIterations, setMaxIterations] = useState<number>(1000);
    const [loading, setLoading] = useState<boolean>(false);
    const [result, setResult] = useState<SolutionResponse | null>(null);
    const [leftPanelExpanded, setLeftPanelExpanded] = useState<boolean>(true);
    const [syncEnabled, setSyncEnabled] = useState<boolean>(true);

    // Обновление текстового представления при изменении матрицы/вектора
    useEffect(() => {
        if (syncEnabled) {
            setTextValue(formatMatrixToString(matrix, vector));
        }
    }, [matrix, vector, n, syncEnabled]);

    // Инициализация матрицы при изменении n
    useEffect(() => {
        if (inputMode === 'manual' || inputMode === 'text') {
            const newMatrix = Array(n).fill(0).map(() => Array(n).fill(0));
            const newVector = Array(n).fill(0);
            setMatrix(newMatrix);
            setVector(newVector);
        }
        setResult(null);
    }, [n, inputMode]);

    const handleNChange = (newN: number) => {
        if (newN > 20) {
            toast.error('Максимальная размерность - 20');
            return;
        }
        if (newN < 1) {
            toast.error('Размерность должна быть положительной');
            return;
        }
        setN(newN);
    };

    const handleFileData = (data: FileData) => {
        setN(data.matrix.length);
        setMatrix(data.matrix);
        setVector(data.vector);
        setResult(null);
        toast.success('Матрица загружена из файла');
    };

    const handleMatrixChange = (newMatrix: number[][], newVector: number[]) => {
        setMatrix(newMatrix);
        setVector(newVector);
        setResult(null);
    };

    const handleTextChange = (newText: string) => {
        setTextValue(newText);
        // Если синхронизация включена, пробуем распарсить и обновить матрицу
        if (syncEnabled) {
            try {
                // Временно отключаем синхронизацию, чтобы избежать цикла
                setSyncEnabled(false);

                // Пробуем распарсить, но не показываем ошибки пользователю
                const lines = newText.trim().split('\n')
                    .map(line => line.trim())
                    .filter(line => line.length > 0);

                if (lines.length >= 2) {
                    const parsedN = parseInt(lines[0]);
                    if (!isNaN(parsedN) && parsedN > 0 && parsedN <= 20 && lines.length - 1 === parsedN) {
                        const newMatrix: number[][] = [];
                        const newVector: number[] = [];

                        for (let i = 1; i <= parsedN; i++) {
                            const parts = lines[i].split(/\s+/).filter(p => p.length > 0);
                            if (parts.length === parsedN + 1) {
                                const row: number[] = [];
                                for (let j = 0; j < parsedN; j++) {
                                    row.push(parseFloat(parts[j]) || 0);
                                }
                                newMatrix.push(row);
                                newVector.push(parseFloat(parts[parsedN]) || 0);
                            }
                        }

                        if (newMatrix.length === parsedN) {
                            setN(parsedN);
                            setMatrix(newMatrix);
                            setVector(newVector);
                        }
                    }
                }

                // Включаем синхронизацию обратно
                setSyncEnabled(true);
            } catch (e) {
                // Игнорируем ошибки парсинга при вводе текста
                setSyncEnabled(true);
            }
        }
    };

    const handleSolve = async () => {
        // Валидация
        for (let i = 0; i < n; i++) {
            if (Math.abs(matrix[i][i]) < 1e-10) {
                toast.error(`Нулевой диагональный элемент в строке ${i + 1}`);
                return;
            }
        }

        setLoading(true);
        try {
            const response = await lab1Api.solve({
                matrix,
                vector,
                params: {
                    epsilon,
                    maxIterations
                }
            });

            setResult(response.data);

            if (response.data.status === 'success') {
                toast.success(response.data.message);
            } else {
                toast.error(response.data.message);
            }
        } catch (error: any) {
            toast.error(error.message || 'Ошибка при решении СЛАУ');
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const syncFromText = () => {
        try {
            const { matrix: newMatrix, vector: newVector } = parseMatrixText(textValue);
            setN(newMatrix.length);
            setMatrix(newMatrix);
            setVector(newVector);
            toast.success('Текст синхронизирован с таблицей');
        } catch (error) {
            toast.error('Ошибка при синхронизации: ' + (error as Error).message);
        }
    };

    return (
        <div className="container mx-auto px-4 py-8 max-w-7xl">
            {/* Шапка с автором и группой - без изменений */}
            <div className="mb-8 bg-white rounded-lg shadow-md p-6">
                <div className="flex justify-between items-start">
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900 mb-2">
                            Лабораторная работа №1: Метод Гаусса-Зейделя
                        </h1>
                        <p className="text-lg text-gray-700">
                            Решение систем линейных алгебраических уравнений
                        </p>
                    </div>
                    <div className="text-right">
                        <p className="text-xl font-semibold text-gray-800">Ясаков Артем Андреевич</p>
                        <p className="text-md text-gray-600">ИСУ: 468198</p>
                        <p className="text-md text-gray-600">Группа: P3213</p>
                    </div>
                </div>
            </div>

            {/* Основной контент с адаптивной шириной */}
            <div className="flex gap-6">
                {/* Левая колонка - ввод данных */}
                <div
                    className={`transition-all duration-300 ${
                        leftPanelExpanded ? 'w-2/3' : 'w-1/3'
                    }`}
                >
                    <div className="bg-white rounded-lg shadow-md p-6">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-xl font-semibold">
                                Ввод данных
                            </h2>
                            <button
                                onClick={() => setLeftPanelExpanded(!leftPanelExpanded)}
                                className="text-sm text-blue-600 hover:text-blue-800 flex items-center gap-1"
                            >
                                {leftPanelExpanded ? (
                                    <>Сжать →</>
                                ) : (
                                    <>← Развернуть</>
                                )}
                            </button>
                        </div>

                        {/* Размерность */}
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Размерность системы (n ≤ 20)
                            </label>
                            <input
                                type="number"
                                min="1"
                                max="20"
                                value={n}
                                onChange={(e) => handleNChange(parseInt(e.target.value) || 1)}
                                className="w-24 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                            />
                        </div>

                        {/* Режим ввода */}
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Способ ввода
                            </label>
                            <div className="flex flex-wrap gap-2">
                                <button
                                    onClick={() => setInputMode('manual')}
                                    className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors ${
                                        inputMode === 'manual'
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                    }`}
                                >
                                    <Grid3x3 className="w-4 h-4" />
                                    Таблица
                                </button>
                                <button
                                    onClick={() => setInputMode('text')}
                                    className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors ${
                                        inputMode === 'text'
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                    }`}
                                >
                                    <FileText className="w-4 h-4" />
                                    Текстовый блок
                                </button>
                                <button
                                    onClick={() => setInputMode('file')}
                                    className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors ${
                                        inputMode === 'file'
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                    }`}
                                >
                                    <Keyboard className="w-4 h-4" />
                                    Из файла
                                </button>
                            </div>
                        </div>

                        {/* Индикатор синхронизации */}
                        {inputMode !== 'file' && (
                            <div className="mb-4 flex items-center justify-between bg-blue-50 p-3 rounded-md">
                                <div className="flex items-center gap-2">
                                    <RefreshCw className={`w-4 h-4 ${syncEnabled ? 'text-blue-600' : 'text-gray-400'}`} />
                                    <span className="text-sm text-blue-700">
                                        {syncEnabled
                                            ? 'Автосинхронизация включена'
                                            : 'Автосинхронизация временно отключена'}
                                    </span>
                                </div>
                                {inputMode === 'text' && !syncEnabled && (
                                    <button
                                        onClick={syncFromText}
                                        className="text-xs bg-blue-600 text-white px-2 py-1 rounded hover:bg-blue-700"
                                    >
                                        Синхронизировать
                                    </button>
                                )}
                            </div>
                        )}

                        {/* Ввод данных */}
                        {inputMode === 'manual' && (
                            <MatrixInput
                                n={n}
                                matrix={matrix}
                                vector={vector}
                                onChange={handleMatrixChange}
                            />
                        )}

                        {inputMode === 'text' && (
                            <MatrixTextInput
                                n={n}
                                value={textValue}
                                onChange={handleTextChange}
                                onSync={syncFromText}
                            />
                        )}

                        {inputMode === 'file' && (
                            <FileUpload onDataLoaded={handleFileData} />
                        )}

                        {/* Параметры метода */}
                        <div className="mt-6 grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Точность (ε)
                                </label>
                                <input
                                    type="number"
                                    min="1e-10"
                                    max="1"
                                    step="1e-6"
                                    value={epsilon}
                                    onChange={(e) => setEpsilon(parseFloat(e.target.value))}
                                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Макс. итераций
                                </label>
                                <input
                                    type="number"
                                    min="1"
                                    max="10000"
                                    value={maxIterations}
                                    onChange={(e) => setMaxIterations(parseInt(e.target.value))}
                                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                />
                            </div>
                        </div>

                        {/* Кнопка решения */}
                        <button
                            onClick={handleSolve}
                            disabled={loading}
                            className="mt-6 w-full bg-green-600 text-white rounded-md hover:bg-green-700 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2 py-3"
                        >
                            {loading ? (
                                <>
                                    <Loader />
                                    <span>Решение...</span>
                                </>
                            ) : (
                                <>
                                    <Play className="w-5 h-5" />
                                    Решить систему
                                </>
                            )}
                        </button>
                    </div>
                </div>

                {/* Правая колонка - результаты (без изменений) */}
                <div
                    className={`transition-all duration-300 ${
                        leftPanelExpanded ? 'w-1/3' : 'w-2/3'
                    }`}
                >
                    <div className="space-y-6">
                        {result ? (
                            <div className="bg-white rounded-lg shadow-md p-6">
                                <h2 className="text-xl font-semibold mb-4">Результаты</h2>

                                {result.status === 'error' ? (
                                    <Alert type="error" message={result.message} />
                                ) : (
                                    <>
                                        <ResultsDisplay result={result} />

                                        {result.iterationHistory && result.iterationHistory.length > 0 && (
                                            <div className="mt-6">
                                                <h3 className="text-lg font-medium mb-3">
                                                    История итераций
                                                </h3>
                                                <IterationTable
                                                    history={result.iterationHistory}
                                                    solution={result.solution}
                                                />
                                            </div>
                                        )}
                                    </>
                                )}
                            </div>
                        ) : (
                            <div className="bg-white rounded-lg shadow-md p-12 flex flex-col items-center justify-center text-center text-gray-500 h-full">
                                <p className="text-lg">Введите данные и нажмите "Решить систему"</p>
                                <p className="text-sm mt-2">Будут отображены результаты решения</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};
